#!/usr/bin/env node
// content-dist drift gate (CLAUDE.md I2, architecture.md §2.2).
//
// content-dist/ is GENERATED by the content build and SHIPPED. It must never be
// hand-edited: any change under content-dist/ must be accompanied by a change
// under content/ (the human-authored source) OR packages/content-build/ (the
// generator itself — a build-logic change can legitimately produce different
// output from unchanged input, e.g. content:build starting to emit a new
// artifact from data that was already there). A content-dist/ diff with
// NEITHER means someone edited the built bundle directly — exactly what this
// gate rejects.
//
// "Changeset" = committed diff against a base ref (default origin/main) UNION
// the working tree (staged, unstaged, and untracked). The working-tree union is
// what lets the M0 exit-criteria demo trip the gate with a single hand-edited
// file, no commit required.
import { execFileSync } from 'node:child_process';

const BASE = process.env.DRIFT_BASE || 'origin/main';

// Returns the command's stdout on success (an empty string IS a valid, meaningful
// result — "the diff is empty"), or null if the command itself failed to run
// (e.g. an unresolvable ref). Collapsing these two outcomes into one falsy value
// was a real bug here: a range that legitimately produced zero output (HEAD
// already equals BASE — the normal state right after any merge, including every
// push-to-main CI run) was indistinguishable from a failed git invocation, so
// the loop below kept falling through past a correct empty diff to a later,
// wrong comparison base. Demonstrated: after merging PR #3 and syncing main
// locally, `git diff --name-only origin/main...HEAD` correctly returned nothing
// (HEAD == origin/main), but the old code fell through to `HEAD~1 HEAD` and
// reported the entire prior commit's file list as "currently changed."
function git(args) {
  try {
    // core.quotepath=false: without it, git renders any non-ASCII path (every
    // kanji filename in this repo) as a double-quoted octal escape sequence,
    // e.g. "content/characters/1/\346\227\245.yaml" instead of 日.yaml — which
    // silently fails the prefix match below and made this gate blind to content/
    // changes the first time a non-ASCII path went through it (M2).
    return execFileSync('git', ['-c', 'core.quotepath=false', ...args], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
    });
  } catch {
    return null; // command failed to run — distinct from a successful empty result
  }
}

const changed = new Set();

// Committed diff vs base (tolerate an unknown base ref: fall back progressively).
// Stop at the first range that actually RAN, whether or not it found changes.
for (const range of [[`${BASE}...HEAD`], [`${BASE}`, 'HEAD'], ['HEAD~1', 'HEAD']]) {
  const out = git(['diff', '--name-only', ...range]);
  if (out !== null) {
    out.split('\n').filter(Boolean).forEach((f) => changed.add(f));
    break;
  }
}

// Working tree: staged + unstaged + untracked.
const status = git(['status', '--porcelain', '--untracked-files=all']) ?? '';
for (const line of status.split('\n').filter(Boolean)) {
  // Porcelain: XY<space>path  (path starts at column 4)
  const path = line.slice(3).trim();
  // Renames appear as "old -> new"; take the destination.
  const arrow = path.indexOf(' -> ');
  changed.add(arrow === -1 ? path : path.slice(arrow + 4));
}

const meaningful = (f, prefix) => f.startsWith(prefix) && !f.endsWith('.gitkeep');

const distChanged = [...changed].filter((f) => meaningful(f, 'content-dist/'));
// A content-dist/ diff is legitimate if EITHER the human-authored source
// (content/) changed, OR the generator itself (packages/content-build/) did —
// a new emitted artifact, or different output for existing content, can come
// from build-logic changing with the input data untouched (e.g. content:build
// starting to emit a new file from data that was already there). Only a
// content-dist/ diff with NEITHER is a hand-edit.
const srcChanged = [...changed].some((f) => meaningful(f, 'content/') || meaningful(f, 'packages/content-build/'));

if (distChanged.length > 0 && !srcChanged) {
  console.error('✗ content-dist drift gate FAILED:\n');
  console.error('  content-dist/ changed with no corresponding change under content/:');
  for (const f of distChanged) console.error('    - ' + f);
  console.error('\n  content-dist/ is generated and shipped; never hand-edit it (I2).');
  console.error('  Edit content/ and regenerate with `pnpm content:build`.');
  process.exit(1);
}

console.log(`✓ content-dist drift gate passed (base ${BASE}; ${distChanged.length} dist change(s), source ${srcChanged ? 'changed' : 'unchanged'}).`);
